#!/usr/bin/env python3

"""Frozen P11 packaging inputs used only by the P12-feature-OFF cohort.

These gzip streams expand to the exact source bytes from the preserved
prxq0011 source snapshot.  Keeping the bytes, their sizes, and their SHA-256
digests together makes the compatibility input explicit and fail-closed
without substituting a digest for the bytes covered by the cohort hash.
"""

import base64
import gzip
import hashlib


_EXPORT_EXTERNAL_APPS_GZIP_BASE64 = b"""

"""

_EXTERNAL_APP_INFO_GZIP_BASE64 = b"""

"""

_EXPECTED = {
    "export_external_apps.py": (
        15076,
        "4be475001a9fd521d9c5f8b574e1f87ec63881ff218b46f0db80744712f45e79",
    ),
    "external_app_info.py": (
        1065,
        "89430579316100e446b74c9b5b706f11ec47a633ecb2af8a30c795d1749fe6a3",
    ),
}


def _decode(name, encoded):
    payload = gzip.decompress(base64.b64decode(encoded))
    expected_size, expected_sha256 = _EXPECTED[name]
    actual_sha256 = hashlib.sha256(payload).hexdigest()
    if len(payload) != expected_size or actual_sha256 != expected_sha256:
        raise ValueError(
            f"frozen prxq0011 cohort input {name} failed provenance validation"
        )
    return payload


def packaging_source_inputs():
    """Return exact name/payload pairs used by the P11 cohort derivation."""
    return {
        "export_external_apps.py": _decode(
            "export_external_apps.py",
            _EXPORT_EXTERNAL_APPS_GZIP_BASE64,
        ),
        "external_app_info.py": _decode(
            "external_app_info.py",
            _EXTERNAL_APP_INFO_GZIP_BASE64,
        ),
    }
